  width: 22px;
  height: 22px;
}

.card-header h1 {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--text-primary);
}

.card-header p {
  font-size: .875rem;
  color: var(--text-secondary);
}

/* ── Form ── */
form {
  padding: 1.75rem 2rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ── Form Field ── */
.form-field fieldset {
  border: none;
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

.form-field legend {
  font-size: .9375rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: .875rem;
  line-height: 1.4;
}

/* ── Radio Options ── */
.radio-option {
  display: flex;
  align-items: center;
  gap: .875rem;
  padding: .875rem 1rem;
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  user-select: none;
  -webkit-user-select: none;
}

.radio-option:hover {
  border-color: var(--brand);
  background: var(--brand-light);
}

.radio-option input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom radio circle */
.radio-custom {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border: 2px solid var(--border);
  border-radius: 50%;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition);
  position: relative;
}

.radio-custom::after {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  transform: scale(0);
  transition: transform var(--transition);
}

/* Checked state */
.radio-option input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--brand);
  background: var(--brand);
}

.radio-option input[type="radio"]:checked ~ .radio-custom::after {
  transform: scale(1);
}

.radio-option:has(input[type="radio"]:checked) {
  border-color: var(--brand);
  background: var(--brand-light);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, .12);
}

/* Focus-visible ring for keyboard nav */
.radio-option input[type="radio"]:focus-visible ~ .radio-custom {
  outline: 3px solid var(--brand);
  outline-offset: 2px;
}

/* Label text */
.radio-content {
  display: flex;
  flex-direction: column;
  gap: .1rem;
}

.radio-label {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--text-primary);
}

.radio-desc {
  font-size: .8125rem;
  color: var(--text-secondary);
}

/* ── Validation error ── */
.error-msg {
  font-size: .8125rem;
  color: #dc2626;
  margin-top: .625rem;
  min-height: 1.2em;
}

.form-field.has-error fieldset {
  animation: shake .3s ease;
}

.form-field.has-error .radio-option {
  border-color: #fca5a5;
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25%       { transform: translateX(-4px); }
  75%       { transform: translateX(4px); }
}

/* ── Submit Button ── */
.submit-btn {
  width: 100%;
  padding: .875rem 1.5rem;
  background: var(--brand);
  color: #fff;
  font-size: .9375rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  letter-spacing: .01em;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.submit-btn:hover {
  background: var(--brand-dark);
  box-shadow: 0 6px 16px -2px rgba(108,99,255,.4);
}

.submit-btn:active {
  transform: translateY(1px);
  box-shadow: none;
}

.submit-btn:focus-visible {
  outline: 3px solid var(--brand);
  outline-offset: 3px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%) translateY(80px);
  background: #1a1a2e;
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  opacity: 0;
  pointer-events: none;
  transition: transform .3s cubic-bezier(.34,1.56,.64,1), opacity .3s ease;
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
