const errorMsg = document.getElementById('form-error');
const toast = document.getElementById('toast');

let toastTimer;

function showToast(message) {
  clearTimeout(toastTimer);
  toast.textContent = message;
  toast.classList.add('show');
  toastTimer = setTimeout(() => toast.classList.remove('show'), 3000);
}

function clearError() {
  formField.classList.remove('has-error');
  errorMsg.textContent = '';
}

form.addEventListener('change', clearError);

form.addEventListener('submit', (e) => {
  e.preventDefault();

  const selected = form.querySelector('input[name="notification"]:checked');

  if (!selected) {
    formField.classList.add('has-error');
    errorMsg.textContent = 'Please select a notification preference to continue.';
    form.querySelector('input[name="notification"]').focus();
    return;
  }

  clearError();

  const labels = { email: 'Email', sms: 'SMS', push: 'Push Notifications' };
  showToast(`✓ Saved! You'll receive notifications via ${labels[selected.value]}.`);
});

